import Foundation

/// Every user-facing string goes through here. The key is the English text;
/// the Spanish text lives in Localizable.xcstrings (generated by
/// tools/gen-strings.py, which also checks that no key is missing).
func L(_ key: String) -> String {
    NSLocalizedString(key, comment: "")
}

/// `L` with `String(format:)` arguments.
func L(_ key: String, _ arguments: CVarArg...) -> String {
    String(format: NSLocalizedString(key, comment: ""), locale: Locale.current, arguments: arguments)
}
